import {TOWERS,statsFor} from './data/towers.js';
import {nearestRoad} from './levels.js';
import {distance,hit} from './enemies.js';
export {TOWERS,statsFor};
const randomDamage=s=>s.damage[0]+Math.random()*(s.damage[1]-s.damage[0]);
export function respawnSquad(g,t){g.soldiers=g.soldiers.filter(s=>s.tower!==t.id);if(t.type!=='barracks'&&t.branch!=='soulforge')return;const stats=statsFor(t),count=t.type==='barracks'?3:1;for(let i=0;i<count;i++){g.soldiers.push({tower:t.id,x:t.rally.x+(i-1)*7,y:t.rally.y+(i%2)*5,hp:stats.hp,maxHP:stats.hp,armor:stats.armor,attack:0,respawn:0,slot:i,sprite:t.branch==='soulforge'?110:t.branch==='wolfpack'?112:96});}}
export function build(g,type,index){if(g.outcome||g.paused||!TOWERS[type]||!g.level.plots[index]||g.towers.some(t=>t.plot===index))return false;if(g.difficulty==='iron'&&['artillery','barracks'].includes(type)){g.notify('Iron challenge: archers and sanctums only');return false;}const stat=TOWERS[type].tiers[0];if(g.gold<stat.cost){g.notify('Not enough gold');return false;}const [x,y]=g.level.plots[index];const t={id:g.nextId++,type,tier:0,branch:null,plot:index,x,y,spent:stat.cost,attack:.2,rally:nearestRoad(g.path,x,y)};g.gold-=stat.cost;g.towers.push(t);respawnSquad(g,t);g.audio.play('build');g.selection={kind:'tower',id:t.id};g.notify(`${TOWERS[type].name} ready`);return true;}
export function upgrade(g,t,branch){if(g.outcome||g.paused||!t||t.branch)return false;const s=t.tier<2?TOWERS[t.type].tiers[t.tier+1]:TOWERS[t.type].branches[branch];if(!s||g.gold<s.cost){g.notify('Not enough gold');return false;}g.gold-=s.cost;t.spent+=s.cost;if(t.tier<2)t.tier++;else t.branch=branch;respawnSquad(g,t);g.audio.play('build');return true;}
export function sell(g,t){if(g.paused||g.outcome||!t)return;g.gold+=Math.floor(t.spent*.7);g.towers=g.towers.filter(x=>x!==t);g.soldiers=g.soldiers.filter(s=>s.tower!==t.id);g.selection=null;g.audio.play('coin');}
export function updateTowers(g,dt){for(const t of g.towers){const s=statsFor(t);t.attack-=dt;const buff=1+g.meta.towers*.05+(g.banner&&distance(t,g.banner)<72?.3:0);if(t.type==='barracks'||t.attack>0)continue;const targets=g.enemies.filter(e=>e.hp>0&&distance(t,e)<s.range&&(t.type!=='artillery'||!e.air)).sort((a,b)=>b.progress-a.progress);if(!targets.length)continue;t.attack=s.rate;const e=targets[0],damage=randomDamage(s)*buff;if(t.type==='artillery'){for(const victim of targetsFrom(g,e,30))if(!victim.air){hit(g,victim,damage*Math.max(.25,1-distance(e,victim)/38));if(t.branch==='napalm')victim.burn=5;if(t.branch==='concussive')victim.slow=4;}g.effects.push({type:'ring',x:e.x,y:e.y,r:30,life:.45,color:'#e9a058'});g.audio.play('blast');}else{const victims=t.branch==='volley'?targets.slice(0,3):[e];for(const victim of victims){hit(g,victim,damage,t.type==='magic'?'magic':'physical');if(t.branch==='hexweaver')victim.curse=5;g.effects.push({type:'bolt',x:t.x,y:t.y-20,tx:victim.x,ty:victim.y,color:TOWERS[t.type].color,life:.14});}g.audio.play(t.type==='magic'?'magic':'arrow');}}
 for(const s of g.soldiers){const t=g.towers.find(t=>t.id===s.tower);if(!t&&!s.militia)continue;const stat=s.militia?{damage:[5,8],rate:1.1}:statsFor(t);if(s.hp<=0){s.respawn-=dt;if(s.respawn<=0&&!s.militia){s.hp=s.maxHP;s.x=t.rally.x+(s.slot-1)*7;s.y=t.rally.y;}continue;}if(s.militia&&(s.life-=dt)<=0){s.hp=0;continue;}const target=g.enemies.find(e=>!e.air&&!e.tunneling&&e.hp>0&&distance(s,e)<16);s.attack-=dt;if(target&&s.attack<=0){hit(g,target,(stat.damage?randomDamage(stat):12)*(1+g.meta.towers*.05)*(g.banner&&distance(s,g.banner)<72?1.3:1));s.attack=stat.rate||1.2;}if(!target&&t){const dest={x:t.rally.x+(s.slot-1)*7,y:t.rally.y+(s.slot%2)*5},d=distance(s,dest);if(d>2){s.x+=(dest.x-s.x)/d*25*dt;s.y+=(dest.y-s.y)/d*25*dt;}}}g.soldiers=g.soldiers.filter(s=>!s.militia||s.hp>0);
}
export const targetsFrom=(g,p,r)=>g.enemies.filter(e=>e.hp>0&&distance(p,e)<r);
